function maxPoints(points: number[][]): number {
    const n = points[0].length;
    const f: number[] = new Array(n).fill(0);
    for (const p of points) {
        const g: number[] = new Array(n).fill(0);
        let lmx = -Infinity;
        let rmx = -Infinity;
        for (let j = 0; j < n; ++j) {
            lmx = Math.max(lmx, f[j] + j);
            g[j] = Math.max(g[j], p[j] + lmx - j);
        }
        for (let j = n - 1; ~j; --j) {
            rmx = Math.max(rmx, f[j] - j);
            g[j] = Math.max(g[j], p[j] + rmx + j);
        }
        f.splice(0, n, ...g);
    }
    return Math.max(...f);
}

class Solution {
public:
    long long maxPoints(vector<vector<int>>& points) {
        const int n = int(points[0].size());
        vector<vector<long long>> dp(2, vector<long long>(n));
        for (int i = 0; i < n; ++i) {
            dp[0][i] = points[0][i];
        }
        int last = 0;
        for (int i = 1; i < points.size(); ++i) {
            int now = last ^ 1;
            long long temp = 0;
            for (int j = 0; j < n; ++j) {
                temp = max(temp, dp[last][j] + j);
                dp[now][j] = temp - j + points[i][j];
            }
            temp = -n;
            for (int j = n - 1; j >= 0; --j) {
                temp = max(temp, dp[last][j] - j);
                dp[now][j] = max(dp[now][j], temp + j + points[i][j]);
            }
            last = now;
        }
        return *max_element(dp[last].begin(), dp[last].end());
    }
};

class Solution {
    public long maxPoints(int[][] points) {
        final int n = points[0].length;
        long[] lastDp = Arrays.stream(points[0]).mapToLong(x -> x).toArray();
        for (int i = 1; i < points.length; ++i) {
            long[] currentDp = new long[n];
            long temp = 0;
            for (int j = 0; j < n; ++j) {
                temp = Math.max(temp, lastDp[j] + j);
                currentDp[j] = temp - j + points[i][j];
            }
            temp = -n;
            for (int j = n - 1; j >= 0; --j) {
                temp = Math.max(temp, lastDp[j] - j);
                currentDp[j] = Math.max(currentDp[j], temp + j + points[i][j]);
            }
            lastDp = currentDp;
        }
        long ans = lastDp[0];
        for (long x : lastDp) {
            ans = Math.max(ans, x);
        }
        return ans;
    }
}

class Solution:
    def maxPoints(self, points: List[List[int]]) -> int:
        n = len(points[0])
        lastDp = points[0]
        for i in range(1, len(points)):
            currentDp = []
            temp = 0;
            for j in range(n):
                temp = max(temp, lastDp[j] + j)
                currentDp.append(temp - j + points[i][j])
            temp = -n;
            for j in reversed(range(n)):
                temp = max(temp, lastDp[j] - j)
                currentDp[j] = max(currentDp[j], temp + j + points[i][j])
            lastDp = currentDp
        return max(lastDp)
